import React from 'react';

import { TreeMapDownloadDataButton } from './TreeMapDownloadDataButton.js';
import { ChartToolbarRenderer } from '../../../core/components/toolbar/ChartToolbarRenderer.js';
import { DEFAULT_TOOLBAR_PLACEMENT } from '../../constants.js';
import { useToolbarConfig } from '../../context/ToolbarContext.js';
import { useTooltip } from '../../hooks/useTooltip.js';
import { useOverlayState } from '../../store/selectors.js';

const initialState = [
  {
    download: 0,
  },
];

export const TreeMapToolbar = () => {
  const toolbarConfig = useToolbarConfig();
  const { mouseInBounds } = useOverlayState();
  const { setTooltipVisible, setTooltipPinned } = useTooltip();
  const toolbarPlacement =
    toolbarConfig?.placement ?? DEFAULT_TOOLBAR_PLACEMENT;

  const handleMouseEnter = () => {
    setTooltipVisible(false);
    setTooltipPinned(false);
  };

  const handleMouseLeave = () => {
    setTooltipVisible(true);
  };

  return (
    <ChartToolbarRenderer
      visible={mouseInBounds}
      placement={toolbarPlacement}
      collapsed={toolbarConfig?.collapsed}
      draggable={toolbarConfig?.draggable}
      initialA11yState={initialState}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      {toolbarConfig?.downloadData?.enabled && <TreeMapDownloadDataButton />}
    </ChartToolbarRenderer>
  );
};
